/*
 * A consumer as it compiled against the headers of Egress 0.23.0, frozen.
 *
 * Each switch below names every enumerator a public result type had at that
 * release and has NO default, the way a consumer built with -Werror=switch
 * may be written. It is compiled, not run, against the current headers.
 *
 * DO NOT edit this file to make it compile. When it stops compiling, an
 * enumerator was added to a public enumeration: that keeps the ABI and
 * breaks such a consumer's build, which is what happened to maelys-warden
 * when 0.23.0 added MAELYS_EGRESS_CLIENT_ERR_BUSY. The change may still be
 * right. Make it a decision: add the enumerator here, re-freeze the release
 * named above, AND write a "Consumer notice" line in CHANGELOG.md saying
 * which enumeration grew, as AGENTS.md requires.
 */
#include <maelys/egress.h>
#include <maelys/egress_channel.h>
#include <maelys/egress_client.h>

int frozen_egress_result(maelys_egress_result_t result);
int frozen_channel_status(maelys_egress_channel_status_t status);
int frozen_client_result(maelys_egress_client_result_t result);

int frozen_egress_result(maelys_egress_result_t result) {
    switch (result) {
    case MAELYS_EGRESS_OK: return 0;
    case MAELYS_EGRESS_ERR_ARGUMENT: return 1;
    case MAELYS_EGRESS_ERR_MEMORY: return 1;
    case MAELYS_EGRESS_ERR_STATE: return 1;
    case MAELYS_EGRESS_ERR_IO: return 1;
    case MAELYS_EGRESS_ERR_DENIED: return 1;
    case MAELYS_EGRESS_ERR_PROTOCOL: return 1;
    case MAELYS_EGRESS_ERR_TIMEOUT: return 1;
    case MAELYS_EGRESS_ERR_CANCELLED: return 1;
    case MAELYS_EGRESS_ERR_UNSUPPORTED: return 1;
    case MAELYS_EGRESS_ERR_CRYPTO: return 1;
    }
    return 1;
}

int frozen_channel_status(maelys_egress_channel_status_t status) {
    switch (status) {
    case MAELYS_EGRESS_CHANNEL_OK: return 0;
    case MAELYS_EGRESS_CHANNEL_DENIED: return 1;
    case MAELYS_EGRESS_CHANNEL_TIMEOUT: return 1;
    case MAELYS_EGRESS_CHANNEL_CANCELLED: return 1;
    case MAELYS_EGRESS_CHANNEL_MALFORMED: return 1;
    case MAELYS_EGRESS_CHANNEL_UNSUPPORTED: return 1;
    case MAELYS_EGRESS_CHANNEL_RESOURCE: return 1;
    case MAELYS_EGRESS_CHANNEL_INTERNAL: return 1;
    }
    return 1;
}

int frozen_client_result(maelys_egress_client_result_t result) {
    switch (result) {
    case MAELYS_EGRESS_CLIENT_OK: return 0;
    case MAELYS_EGRESS_CLIENT_ERR_ARGUMENT: return 1;
    case MAELYS_EGRESS_CLIENT_ERR_IO: return 1;
    case MAELYS_EGRESS_CLIENT_ERR_UNANSWERED: return 1;
    case MAELYS_EGRESS_CLIENT_ERR_PROTOCOL: return 1;
    case MAELYS_EGRESS_CLIENT_ERR_DENIED: return 1;
    case MAELYS_EGRESS_CLIENT_ERR_TIMEOUT: return 1;
    case MAELYS_EGRESS_CLIENT_ERR_CANCELLED: return 1;
    case MAELYS_EGRESS_CLIENT_ERR_UNSUPPORTED: return 1;
    case MAELYS_EGRESS_CLIENT_ERR_RESOURCE: return 1;
    case MAELYS_EGRESS_CLIENT_ERR_INTERNAL: return 1;
    case MAELYS_EGRESS_CLIENT_ERR_BUSY: return 1;
    }
    return 1;
}
